css_snippet:
/* Align numbers perfectly in tables or data grids */
.data-table, .price-list {
  font-variant-numeric: tabular-nums;
  /* Ensures all numbers occupy the same horizontal space */
}

/* Display elegant, stacked fractions */
.article-content .fraction {
  font-variant-numeric: diagonal-fractions;
  /* Transforms '1/2' into a proper typographic fraction */
}

/* Use classic, varying-height numbers in body text for aesthetic flow */
.body-text {
  font-variant-numeric: old-style-nums;
  /* 'old-style-nums' gives a more traditional, calligraphic feel */
}

/* Combine features for specific UI elements */
.product-specs {
  font-variant-numeric: old-style-nums slashed-zero;
  /* Old-style for elegance, slashed-zero to distinguish '0' from 'O' */
}
